commits.content:
.form {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  box-sizing: border-box;
  margin-top: 0; /* Обнулили, так как внешнее позиционирование теперь в потоке */
  margin-left: 15px; /* Выставили точные макетные 15px от людей */
  width: 390px;
  height: 468.8px;
  border-radius: 15px;
  border: solid 2px #ff7a00;
  background-color: #1c1d1e;
}

.title {
  padding-top: 24.25px;
  padding-left: 50px;
  font-size: 22px;
  font-weight: 400;
  line-height: 27px;
  letter-spacing: 0.05em;
  color: #ffffff;
}

.label {
  margin-left: 50px;
  margin-top: 23.24px;
  font-size: 14px;
  font-weight: 500;
  font-stretch: normal;
  font-style: normal;
  line-height: normal;
  letter-spacing: 0.7px;
  text-align: left;
  color: #fff;
}

.line {
  width: 285px;
  border-top: 2px solid #ff7a00;
  box-sizing: border-box;
  margin-left: 51px;
  margin-top: 3.1px;
}

.label:nth-of-type(2) {
  margin-top: 18.2px;
}

.label:nth-of-type(3) {
  margin-top: 17.2px;
  margin-left: 51px;
}

.label_name {
  margin-top: 23.24px;
  margin-left: 50px;
}

.label_phone {
  margin-top: 18.2px;
  margin-left: 50px;
}

.label_text {
  margin-top: 17.2px;
  margin-left: 51px;
}

.textarea {
  width: 285px;
  height: 146.53px;
  border-radius: 10px;
  border: 2px solid #ff7a00;
  background: transparent;
  box-sizing: border-box;
  margin-top: 16.7px;
  margin-left: 51px;
  color: #ffffff;
  padding: 10px 14px;
  outline: none;
  resize: none;
}

.textarea::-webkit-scrollbar {
  display: none;
}

.submitBtn {
  width: 285px;
  height: 50.53px;
  border-radius: 10px;
  border: 2px solid #ff7a00;
  background: transparent;
  box-sizing: border-box;
  margin-top: 25.27px;
  margin-left: 51px;
  cursor: pointer;
  color: #ffffff;
  transition: background-color 0.3s ease, color 0.3s ease;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.8px;
}

.submitBtn:hover {
  background-color: #ff7a00;
  color: #1c1d1e;
}

.input {
  background: transparent;
  border: none;
  outline: none;
  color: #ffffff;
  box-sizing: border-box;
}

.checkboxText {
  font-family: "Montserrat", sans-serif;
  font-style: normal;
  font-weight: 400;
  font-size: 10px;
  line-height: 12px;
  letter-spacing: 5%;
  color: #ffffff;
  text-align: left;
}

.checkboxContainer {
  display: flex;
  align-items: center;
  margin-top: 16.1px;
  margin-left: 51px;
  cursor: pointer;
}

.checkboxHidden {
  opacity: 0;
  position: absolute;
  width: 0;
  height: 0;
}

.checkboxCustom {
  width: 16px;
  height: 16.17px;
  border: 1px solid #ff7a00;
  border-radius: 5px;
  background: transparent;
  box-sizing: border-box;
  margin-right: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
